const crypto = require('crypto');
if (!$env.IFC_SERVICE_URL) throw new Error('Missing IFC_SERVICE_URL');
const report = await this.helpers.httpRequest({method:'POST',url:$env.IFC_SERVICE_URL+'/reports/extract',json:true,body:{pdfB64:""}});
if (!report.text.includes('CBM runtime PDF fixture')) throw new Error('PDF text not extracted');
const base=$env.IFC_SERVICE_URL;
const health=await this.helpers.httpRequest({method:'GET',url:base+'/health',json:true});
const prepared=await this.helpers.prepareBinaryData(Buffer.from('CBM binary test'), 'fixture.txt','text/plain');
const normalized=await this.helpers.httpRequest({method:'POST',url:base+'/captures/normalize',json:true,body:{imageB64:"",longSide:1280}});
if(!normalized.camera.trusted) throw new Error('Untrusted synthetic EXIF camera');
const caseStatus=await this.helpers.httpRequest({method:'GET',url:base+'/case-study/status',json:true});
const assets=await this.helpers.httpRequest({method:'GET',url:base+'/elements',json:true});
if(assets.count!==13 || !assets.elements.some(x=>x.global_id==='3kcZF9AH16IwPfuL_CGFlR' && x.ifc_class==='IfcBuildingElementProxy')) throw new Error('Wrong case-study IFC');
if(normalized.camera.calibrated!==false) throw new Error('EXIF estimate mislabeled as calibration');
return [{json:{ok:true,pdfParser:report.parser,activeModel:health.active_model,assetCount:assets.count,
caseStatus,cryptoSha256:crypto.createHash('sha256').update('CBM').digest('hex'),cameraCalibrated:false},binary:{data:prepared}}];
